    if (!match) return null;
    const start = Number(match[1]);
    const end = Number(match[2]);
    return start >= 1 && end >= start ? { start, end } : null;
}

export function summarizeRun(records) {
    const list = Array.isArray(records) ? records : [];
    let billableTokens = 0;
    let maxContext = 0;
    for (const record of list) {
        const input = Number(record?.inputTokens) || 0;
        const output = Number(record?.outputTokens) || 0;
        const total = input + output;
        billableTokens += total;
        if (total > maxContext) maxContext = total;
    }
    return { requests: list.length, billableTokens, maxContext };
}
